from collections import deque
from math import floor


class PrivateLotStrategySystem(QCAlgorithm):
    SMA_PERIOD = 50

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.closes = {symbol: deque(maxlen=self.SMA_PERIOD + 1) for symbol in self.symbols}
        self.previous_close = {symbol: None for symbol in self.symbols}
        self.red_streak = {symbol: 0 for symbol in self.symbols}

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars = {}

        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bars[symbol] = data.Bars[symbol]

        for symbol, bar in bars.items():
            previous = self.previous_close[symbol]

            if previous is not None and bar.Close < previous:
                self.red_streak[symbol] += 1
            else:
                self.red_streak[symbol] = 0

            self.previous_close[symbol] = bar.Close
            self.closes[symbol].append(float(bar.Close))

            if symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

        if len(bars) != len(self.symbols):
            return

        if len(self.closes[self.spy]) < self.SMA_PERIOD + 1:
            return

        if not self.aapl_rsi.IsReady:
            return

        spy_closes = self.closes[self.spy]
        spy_close = float(bars[self.spy].Close)

        yesterday_sma = sum(list(spy_closes)[1:]) / self.SMA_PERIOD
        today_sma = sum(list(spy_closes)[:self.SMA_PERIOD]) / self.SMA_PERIOD

        yesterday_spy_close = list(spy_closes)[-2]
        spy_crosses_above_sma = yesterday_spy_close <= yesterday_sma and spy_close > today_sma
        spy_crosses_below_sma = yesterday_spy_close >= yesterday_sma and spy_close < today_sma

        aapl_close = float(bars[self.aapl].Close)
        aapl_red_for_three_days = self.red_streak[self.aapl] >= 3
        aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below_sma:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above_sma:
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            quantity = int(floor(target_value / spy_close))

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and aapl_red_for_three_days:
            purchase_value = 20_000

            if self.Portfolio.Cash >= purchase_value:
                quantity = int(floor(purchase_value / aapl_close))

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity
