class SpecifiedStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fill_forward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fill_forward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fill_forward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fill_forward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fill_forward=False).Symbol

        self.spy_sma = self.SMA(self.spy, 200, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.a_lot = 0
        self.b_lot = 0

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.spy_samples = 0
        self.aapl_samples = 0

    def OnData(self, data):
        if self.spy in data.Bars:
            self.spy_samples += 1

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close
            self.aapl_samples += 1

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        if not all(symbol in data.Bars for symbol in required_symbols):
            return

        if (
            self.spy_samples < 201
            or self.aapl_samples < 4
            or not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_close = data.Bars[self.spy].Close
        previous_spy_close = self.spy_sma.Previous.Input.Value
        spy_sma_value = self.spy_sma.Current.Value
        previous_spy_sma_value = self.spy_sma.Previous.Value

        spy_crosses_above_sma = (
            previous_spy_close <= previous_spy_sma_value
            and spy_close > spy_sma_value
        )
        spy_crosses_below_sma = (
            previous_spy_close >= previous_spy_sma_value
            and spy_close < spy_sma_value
        )

        # Evaluate sells before buys.
        if self.a_lot > 0 and spy_crosses_below_sma:
            self.MarketOrder(self.spy, -self.a_lot)
            self.a_lot = 0

        if self.b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.b_lot)
            self.b_lot = 0

        if self.a_lot == 0 and spy_crosses_above_sma:
            shares = int(
                float(self.Portfolio.TotalPortfolioValue * 0.40 / spy_close)
            )
            if shares > 0:
                ticket = self.MarketOrder(self.spy, shares)
                if ticket.Status != OrderStatus.Invalid:
                    self.a_lot = shares

        if self.b_lot == 0 and self.aapl_red_streak >= 3:
            aapl_close = data.Bars[self.aapl].Close
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 / float(aapl_close))
                if shares > 0:
                    ticket = self.MarketOrder(self.aapl, shares)
                    if ticket.Status != OrderStatus.Invalid:
                        self.b_lot = shares
